detaileddescription.para:
To free memory, use reset() to free all allocations, or restore() to rollback to a checkpoint, or let the arena be destroyed.

no-op behavior autoarena=cslt::move(cslt::ArenaAllocator::Heap(4096).value());

void*ptr=arena->alloc(256).value();
size_tsize_before=arena->size();

//Thisdoesnothing
arena->return_element(ptr,256);

//Sizeunchanged-memorystillallocated
assert(arena->size()==size_before);

//Toactuallyfreememory:
arena->reset();
assert(arena->size()==0);
